import '../../../../../../Core/Models/product_details_model.dart';class ProductDetailsEntities extends ProductDetailsModel {  ProductDetailsEntities({    required super.name,    required super.description,    required super.additionalInfo,    required super.price,    required super.discountPrice,    required super.dimensions,    required super.status,    required super.quantity,    required super.images,    required super.colors,    required super.sizes,    required super.materials,    required super.reviews,  }) : super(          slug: "",          id: 0,          createdAt: null,          updatedAt: null,          featured: 0,          popular: 0,          categoryId: 0,        );  factory ProductDetailsEntities.fromProduct(ProductDetailsModel product) {    return ProductDetailsEntities(      name: product.name,      description: product.description,      additionalInfo: product.additionalInfo,      price: product.price,      discountPrice: product.discountPrice,      dimensions: product.dimensions,      status: product.status,      quantity: product.quantity,      images: product.images,      colors: product.colors,      sizes: product.sizes,      materials: product.materials,      reviews: product.reviews,    );  }  Map<String, dynamic> toMap() {    return {      'name': name,      'slug': slug,      'category_id': categoryId,      'description': description,      'additional_info': additionalInfo,      'price': price,      'discount_price': discountPrice,      'dimensions': dimensions,      'status': status,      'quantity': quantity,      'images': images,      'colors': colors,      'sizes': sizes,      'materials': materials,      'reviews': reviews,    };  }}